<template><AdministrationLayout search-placeholder="N° de demande, client…" v-slot="{search}"><section class="demandes"><header class="title"><span>▣</span><div><h1>Supervision des demandes</h1><p>Liste des pannes signalées. Cliquez sur "Voir plus" pour consulter l'intégralité du dossier.</p></div></header><section class="filters"><b>Filtres :</b><button v-for="filter in filters" :key="filter.key" :class="[filter.key,{selected:active===filter.key}]" @click="active=filter.key">{{filter.icon}}　 {{filter.label}}</button></section><TableauDemandes :demandes="visible(search)" @detail="selected=$event" @delete="removeItem"/><footer class="bottom"><span>Affichage de 1 à {{visible(search).length}} sur 3450 demandes</span><div><button>‹</button><button class="current">1</button><button v-for="n in 4" :key="n">{{n+1}}</button><button>›</button></div></footer></section><DetailDemandeModal v-if="selected" :demande="selected" @close="selected=null"/></AdministrationLayout></template>
<script setup>import{ref}from'vue';import AdministrationLayout from '../../components/administrateur/AdministrationLayout.vue';import TableauDemandes from '../../components/administrateur/TableauDemandes.vue';import DetailDemandeModal from '../../modales/administrateur/DetailDemandeModal.vue';import{useDemandes}from'../../services/serviceDemandes';const{demandes,remove}=useDemandes();const active=ref('all'),selected=ref(null);const filters=[{key:'all',icon:'☷',label:'Toutes (3450)'},{key:'En attente',icon:'◔',label:'En attente (12)'},{key:'Acceptée',icon:'✓',label:'Acceptées (45)'},{key:'Terminée',icon:'✓',label:'Terminées (3380)'},{key:'Annulée',icon:'×',label:'Annulées (13)'}];function visible(search){const q=search.toLowerCase();return demandes.value.filter(d=>(active.value==='all'||d.status===active.value)&&JSON.stringify(d).toLowerCase().includes(q))}function removeItem(item){if(window.confirm(`Supprimer la demande ${item.id} ?`))remove(item.id)}</script>
<style scoped>.demandes{display:grid;gap:19px}.title,.filters{background:#fff;border:1px solid #dfecfa;border-radius:10px}.title{height:102px;display:flex;align-items:center;gap:24px;padding:20px 23px}.title>span{width:53px;height:53px;display:grid;place-items:center;border-radius:13px;background:#087f70;color:#fff;font-size:27px}.title h1{text-transform:uppercase;font-size:24px;line-height:1;margin:0;color:#092d73}.title p{margin:9px 0 0;color:#5275af;font-size:16px}.filters{height:87px;display:grid;grid-template-columns:72px repeat(5,1fr);gap:30px;align-items:center;padding:14px 19px}.filters>b{font-size:15px;color:#174b50}.filters button{height:47px;border:1px solid #c6ddff;border-radius:11px;background:#f4f9ff;color:#087f70;font-size:14px}.filters button.selected{background:#087f70;color:#fff;box-shadow:0 7px 15px #087f7037}.filters button:nth-of-type(2){background:#fff5e2;border-color:#ffe0a6;color:#e68b00}.filters button:nth-of-type(3){background:#eff8ff}.filters button:nth-of-type(4){background:#edfcf7;border-color:#c7f1df;color:#00a976}.filters button:nth-of-type(5){background:#fff0f2;border-color:#ffd0d7;color:#f03650}.filters button.selected{background:#087f70;color:#fff}.bottom{height:59px;display:flex;justify-content:space-between;align-items:center;padding:5px 12px;color:#6181b6;font-size:13px}.bottom div{display:flex;gap:9px}.bottom button{width:35px;height:35px;border-radius:8px;border:1px solid #d3e4fa;background:#fff;color:#087f70}.bottom .current{background:#087f70;color:#fff}@media(max-width:1050px){.filters{grid-template-columns:repeat(3,1fr);gap:10px;height:auto}.filters>b{grid-column:span 3}}@media(max-width:600px){.title{height:auto;align-items:flex-start}.title h1{font-size:17px}.title p{font-size:12px}.filters{grid-template-columns:1fr 1fr}.filters>b{grid-column:span 2}.bottom{font-size:11px}}</style>
